"""C5VRX by Twotoz and the C5VRX contributors: writes fpga/rtl/lite_rom_init.vh
(block RAM tables) and fpga/rtl/lite_tables.vh (logic tables) of the Tang
Nano 1K lite combiner from lite_model.py.

    python hardware_experiments/tang9k_dual/fpga/model/gen_lite_tables.py
"""
import math
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import lite_model as L  # noqa: E402

RTL = HERE.parent / 'rtl'
HEAD = ['// C5VRX by Twotoz and the C5VRX contributors: TANG9K_DUAL lite (Tang Nano 1K) tables.',
        '// Generated by fpga/model/gen_lite_tables.py from lite_model.py; do not edit.']


def rom(name, bits, vals):
    return [f"    {name}[{i}] = {bits}'h{int(v) & ((1 << bits) - 1):0{(bits + 3) // 4}x};" for i, v in enumerate(vals)]


def func(name, ib, ob, vals, signed=False):
    out = [f'function automatic {"signed " if signed else ""}[{ob - 1}:0] {name};', f'    input [{ib - 1}:0] a;',
           '    begin', '        case (a)']
    for i, v in enumerate(vals):
        v = int(v)
        out.append(f"            {ib}'d{i}: {name} = {'-' if v < 0 else ''}{ob}'{'s' if signed else ''}d{abs(v)};")
    out += [f'            default: {name} = 0;', '        endcase', '    end', 'endfunction', '']
    return '\n'.join(out)


def quadrant_tables():
    """First-quadrant angle (2^-10 turn) and 4 log2|c| of |c| = 2m + 1."""
    qa, ql = [], []
    for mi in range(8):
        for mq in range(8):
            ci, cq = 2 * mi + 1, 2 * mq + 1
            qa.append(int(round(math.atan2(cq, ci) / (2 * math.pi) * 1024)))
            ql.append(int(round(4 * math.log2(math.hypot(ci, cq)))))
    return qa, ql


def check_symmetry(qa, ql):
    for raw in range(256):
        i, q = ((raw >> 4) ^ 8) - 8, ((raw & 15) ^ 8) - 8
        mi, mq = (i if i >= 0 else -i - 1), (q if q >= 0 else -q - 1)
        a = qa[mi * 8 + mq]
        a = {(0, 0): a, (1, 0): 512 - a, (1, 1): 512 + a, (0, 1): 1024 - a}[(int(i < 0), int(q < 0))] & 1023
        assert a == L.T1_ANG[raw] and ql[mi * 8 + mq] == L.T1_LG[raw], raw


def main():
    qa, ql = quadrant_tables()
    check_symmetry(qa, ql)
    (RTL / 'lite_rom_init.vh').write_text('\n'.join(HEAD + ['initial begin'] + rom('th_rom', 8, L.TH)
                                                    + rom('t2_rom', 9, L.T2)
                                                    + rom('t1_rom', 15, [(int(l) << 10) | int(a) for l, a in zip(L.T1_LG, L.T1_ANG)])
                                                    + ['end', '']))
    (RTL / 'lite_tables.vh').write_text('\n'.join(HEAD + [''] + [
        func('q_ang', 6, 8, qa), func('q_lg', 6, 5, ql), func('g_lut', 6, 6, L.g_table(), signed=True),
        func('cos6', 6, 6, L.COS6, signed=True), func('sin6', 6, 6, L.SIN6, signed=True)]))
    print('wrote rtl/lite_rom_init.vh, rtl/lite_tables.vh')


if __name__ == '__main__':
    main()
